fn receipt_set_grant(birth:usize,release:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:birth,maximum_release_bytes:release,maximum_depth:64}}
fn receipt_set_observe(operation:impl FnOnce()->RetainedCloneStep,grant:RetainedCloneGrant){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(operation);assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
fn receipt_set_close(owner:&mut MountedGroupMemberReceipts){for _ in 0..100000{if owner.terminal_is_empty(){break;}let demand=owner.next_close_byte_demand().unwrap();let grant=receipt_set_grant(0,demand);receipt_set_observe(||owner.close_step(RetainedCloneGrant{maximum_items:0,..grant}).unwrap(),receipt_set_grant(0,0));if demand>0{receipt_set_observe(||owner.close_step(receipt_set_grant(0,demand-1)).unwrap(),receipt_set_grant(0,0));}receipt_set_observe(||owner.close_step(grant).unwrap(),grant);}assert!(owner.terminal_is_empty());}
#[test]
fn mounted_group_member_receipts_preserve_noncontiguous_rows_and_exact_all_physical_frames(){
    let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    let original:serde_json::Value=serde_json::from_str(include_str!("../../🧾️receipt/📦️group/👤️member/🧫️fixtures/🔣️.json")).unwrap();
    for case in corpus["cases"].as_array().unwrap(){for stop in [None,Some(0),Some(1),Some(7),Some(31),Some(127),Some(257)]{
        let group=case["groupId"].as_str().unwrap();let actor=case["actor"].as_str().unwrap();let parent=case["parent"].as_bool().unwrap();let children=case["children"].as_u64().unwrap()as usize;
        let mut owner=Box::new(MountedGroupMemberReceipts::from_original(group,actor,ArtifactHandle(41),parent,children).unwrap());let mut fixture=original.clone();fixture["groupId"]=case["groupId"].clone();let mut turns=0;let mut operations=0;
        for(index,count)in case["operations"].as_array().unwrap().iter().enumerate(){let slot=index+usize::from(!parent);let count=count.as_u64().unwrap()as usize;let mut publication=member_receipt_fixture(&fixture,count,2);publication.edit=case["editIds"][index].as_str().unwrap().to_owned();
            let pointers=publication.forward.iter().map(|body|body.0.as_ptr()).collect::<Vec<_>>();
            for _ in 0..100000{if stop.is_some_and(|stop|turns>=stop){break;}let ordinal=owner.rows.rows[slot].as_ref().and_then(|row|row.operation_index()).unwrap_or(0);let mut source=member_receipt_source(&fixture,&publication,ordinal);source.invocation_id=group;source.group_id=group;source.fallback_author=actor;
                let birth=owner.rows.rows[slot].as_ref().map_or(MountedMemberReceipt::frame_birth_bytes(),|row|row.next_capacity_byte_demand(&source).unwrap());let release=owner.rows.rows[slot].as_ref().map_or(0,|row|row.next_release_byte_demand(&source).unwrap());let grant=receipt_set_grant(birth,release);receipt_set_observe(||owner.advance_row(slot,&source,RetainedCloneGrant{maximum_items:0,..grant}).unwrap(),receipt_set_grant(0,0));if birth>0{receipt_set_observe(||owner.advance_row(slot,&source,receipt_set_grant(birth-1,release)).unwrap(),receipt_set_grant(0,0));}receipt_set_observe(||owner.advance_row(slot,&source,grant).unwrap(),grant);turns+=1;
                assert_eq!(publication.forward.iter().map(|body|body.0.as_ptr()).collect::<Vec<_>>(),pointers);
                if owner.rows.rows[slot].as_ref().unwrap().is_complete(){assert_eq!(owner.rows.rows[slot].as_ref().unwrap().ready_edit_id(),Some(case["editIds"][index].as_str().unwrap()));operations+=count;owner.receipt_cursor=slot+1;break;}
            }
            if stop.is_some_and(|stop|turns>=stop){break;}
        }
        owner.operation_count=operations;
        if stop.is_none(){assert!(owner.ready_for_final());for _ in 0..100000{if owner.final_ready(){break;}let birth=owner.next_final_capacity_byte_demand(group).unwrap();let release=owner.next_final_release_byte_demand();let grant=receipt_set_grant(birth,release);receipt_set_observe(||owner.advance_final(group,RetainedCloneGrant{maximum_items:0,..grant}).unwrap(),receipt_set_grant(0,0));if birth>0{receipt_set_observe(||owner.advance_final(group,receipt_set_grant(birth-1,release)).unwrap(),receipt_set_grant(0,0));}receipt_set_observe(||owner.advance_final(group,grant).unwrap(),grant);}assert!(owner.final_ready());assert_eq!(owner.final_receipt.as_ref().unwrap().mutations.len(),operations);assert_eq!(owner.final_receipt.as_ref().unwrap().member_edits.iter().map(|row|row.edit_id.as_str()).collect::<Vec<_>>(),case["editIds"].as_array().unwrap().iter().map(|id|id.as_str().unwrap()).collect::<Vec<_>>());let pointer=owner.final_receipt.as_ref().unwrap().mutations.as_ptr();assert!(owner.take_final(RetainedCloneGrant{maximum_items:0,..receipt_set_grant(0,0)}).is_none());let(output,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take_final(receipt_set_grant(0,0)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(output.mutations.as_ptr(),pointer);assert_eq!(output.mutations.len(),operations);assert_eq!(output.inverse_group.member_edits.len(),case["editIds"].as_array().unwrap().len());assert_eq!(output.command_child_edit_ids.len(),children);assert_eq!(output.command_edit_id.as_deref(),parent.then(||case["editIds"][0].as_str().unwrap()));drop(output);}
        receipt_set_close(&mut owner);let frame=owner.terminal_frame_byte_demand().unwrap();assert_eq!(frame,MountedGroupMemberReceipts::frame_birth_bytes());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,frame));println!("[DEBUG] member receipt set case={} stop={stop:?} original pointers/ordered operations={operations}, final noncontiguous exact memberIds; complete row edit/backing/Box retirement same-turn System parity",case["name"]);
    }}
}
